def test_cachedmethod_accepts_condition():
    import threading
    import cachetools

    class Service:
        def __init__(self):
            self.cache = {}

        @cachetools.cachedmethod(lambda self: self.cache, condition=threading.Condition())
        def double(self, x):
            return x * 2

    service = Service()
    assert service.double(4) == 8
    assert service.double(4) == 8
    assert len(service.cache) == 1


def test_cached_condition_replaces_lock():
    import threading
    import cachetools

    class ExplodingLock:
        def __enter__(self):
            raise AssertionError('lock must not be used when condition is provided')

        def __exit__(self, *exc):
            raise AssertionError('lock must not be used when condition is provided')

        def acquire(self, *args):
            raise AssertionError('lock must not be used when condition is provided')

        def release(self):
            raise AssertionError('lock must not be used when condition is provided')

    @cachetools.cached(cache={}, lock=ExplodingLock(), condition=threading.Condition())
    def identity(x):
        return x

    assert identity(1) == 1


def test_cached_condition_waits_for_inflight_computation():
    import threading
    import time
    import cachetools

    class TrackingCondition(threading.Condition):
        def __init__(self):
            super().__init__()
            self.waits = 0
            self.notifies = 0

        def wait(self, timeout=None):
            self.waits += 1
            return super().wait(timeout)

        def wait_for(self, predicate, timeout=None):
            self.waits += 1
            return super().wait_for(predicate, timeout)

        def notify(self, n=1):
            self.notifies += 1
            return super().notify(n)

        def notify_all(self):
            self.notifies += 1
            return super().notify_all()

    condition = TrackingCondition()
    calls = 0
    started = threading.Event()
    release = threading.Event()

    def compute(x):
        nonlocal calls
        calls += 1
        started.set()
        release.wait(2)
        return x * 2

    @cachetools.cached(cache={}, condition=condition)
    def double(x):
        return compute(x)

    results = []

    def worker():
        results.append(double(21))

    first = threading.Thread(target=worker)
    first.start()
    assert started.wait(1)

    second = threading.Thread(target=worker)
    second.start()

    deadline = time.time() + 1
    while condition.waits == 0 and time.time() < deadline:
        time.sleep(0.01)

    release.set()
    first.join(2)
    second.join(2)

    assert not first.is_alive()
    assert not second.is_alive()
    assert calls == 1
    assert results == [42, 42]
    assert condition.waits > 0
    assert condition.notifies > 0
