def test_all_cache_decorators_pass_condition_to_cached():
    import threading
    import cachetools.func

    captured = []
    original = cachetools.func.cached

    def spy(*args, **kwargs):
        captured.append(kwargs)
        return original(*args, **kwargs)

    cachetools.func.cached = spy
    try:
        @cachetools.func.fifo_cache(maxsize=2)
        def fifo(x):
            return x

        @cachetools.func.lfu_cache(maxsize=2)
        def lfu(x):
            return x

        @cachetools.func.lru_cache(maxsize=2)
        def lru(x):
            return x

        @cachetools.func.rr_cache(maxsize=2)
        def rr(x):
            return x

        @cachetools.func.ttl_cache(maxsize=2, ttl=60)
        def ttl(x):
            return x
    finally:
        cachetools.func.cached = original

    assert len(captured) == 5
    for kwargs in captured:
        assert isinstance(kwargs.get('condition'), threading.Condition)
        assert kwargs.get('lock') is None


def test_cache_decorators_still_work():
    import cachetools.func

    calls = 0

    @cachetools.func.lru_cache(maxsize=2)
    def square(x):
        nonlocal calls
        calls += 1
        return x * x

    assert square(3) == 9
    assert square(3) == 9
    assert calls == 1
